import{_ as t,o,c as a,a2 as l}from"./chunks/framework.Crpw6aS5.js";const h=JSON.parse('{"title":"2015年 · 生产力与繁荣","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/2015年.md","filePath":"05_quotes/by-year/2015年.md"}'),r={name:"05_quotes/by-year/2015年.md"};function c(u,e,p,q,s,_){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="_2015年-·-生产力与繁荣" tabindex="-1">2015年 · 生产力与繁荣 <a class="header-anchor" href="#_2015年-·-生产力与繁荣" aria-label="Permalink to &quot;2015年 · 生产力与繁荣&quot;">​</a></h1><blockquote><p>美国企业——以及因此一篮子股票——在未来几年几乎肯定会更值钱。创新、生产率提高、企业家精神和充裕的资本将确保这一点。一直存在的悲观主义者可能通过推销他们悲观的预测获利，但如果他们照着那些无稽之谈行事，上天保佑他们。——巴菲特（85岁）</p></blockquote><p>本页收录2015年致股东信中的经典语录。本年以生产力提升如何推动社会繁荣为核心主题，同时深入探讨了保险业务的护城河和克莱顿家园的风险保留模式。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>所有保险公司都对这种说法给予口头支持。但在伯克希尔，这是一种宗教——旧约风格。</p></blockquote><blockquote><p>那句老话，&quot;其他人都在做，所以我们也必须做&quot;，在任何行业都意味着麻烦，但在保险业尤其如此。</p></blockquote><blockquote><p>当CEO或投资银行家将折旧前指标（如EBITDA）作为估值参考时，注意他们的鼻子在说谎时会变长。</p></blockquote><blockquote><p>如果&quot;激励&quot;不是费用，那它是什么？而且，如果真实且经常发生的费用不应该计入收益计算，它们到底属于哪里？</p></blockquote><blockquote><p>GEICO的成本优势是使该公司年复一年吞噬市场份额的因素。其低成本创造了一条护城河——一条持久的护城河——竞争对手无法跨越。</p></blockquote><blockquote><p>在克莱顿家园，我们的风险保留过去是、现在仍然是100%。当我们发起一笔抵押贷款时，我们保留它。当我们在授信时犯了错误，我们会付出代价。</p></blockquote><blockquote><p>生产力提升经常导致动荡：当创新或新效率颠覆它们的世界时，资本和劳动力都可能付出可怕的代价。我们不需要为资本家流泪。照顾自己是他们的工作。</p></blockquote><blockquote><p>这种颠覆的答案不是限制或禁止提高生产力的行动。如果我们命令1100万人应该永远从事农业，美国人就不会生活得几乎像我们这样好。</p></blockquote><blockquote><p>我们只需要少数人真正优秀就够了——管理好资本才是关键。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>2015年伯克希尔每股账面价值增长6.4%，但股价下跌12.5%，标普500仅涨1.4%。本年信首次将保险承保收入纳入内在价值计算，并以农业、铁路和GEICO三个案例深入论述了生产力提升如何推动美国繁荣。巴菲特首次在股东信中讨论气候变化议题。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><p><a href="/01_letters/2015年/翻译.html">01_letters/2015年/翻译</a> · <a href="/01_letters/2015年/核心总结.html">01_letters/2015年/核心总结</a> · <a href="/01_letters/2015年/思维导图.html">01_letters/2015年/思维导图</a></p>',20)])])}const n=t(r,[["render",c]]);export{h as __pageData,n as default};
